{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Compound 9g, a CF3-pyridine anilide with a piperidine amide, showed good brain penetration with a rat brain/plasma ratio of 1.2, supporting that CF3-containing heteroaromatic amide/amine scaffolds can achieve meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Fedratinib, an aminopyrimidine anilide inhibitor with a sulfonamide and ether side chain, showed high unbound brain-to-plasma distribution in rats despite a polar surface area that would predict poor penetration; this directly supports CNS access for similar anilino-pyrimidine kinase-inhibitor-like scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "XL01126 was detected at 14 nM in both brain and CSF in mice despite a total polar surface area of 194 Å², demonstrating that high polar surface area does not preclude meaningful BBB crossing in this chemical class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A tetrahydropyridyl compound with a CF3-pyridine and triflyl anilide gave a rat brain/plasma ratio of 1.5 and was classified as good penetration, supporting CNS access for CF3-containing heteroaromatic amides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Compound 11, a piperazine-containing amide, crossed the BBB and was detected in mouse brain 2 h after exposure, supporting that piperazine/amide scaffolds can achieve brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "PD156707 crossed the BBB as shown by dog CSF levels on day 2, providing direct evidence that even an acid-containing anilino-heteroaryl can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer in vivo, CSF, and PET records from structurally related CF3-containing heteroaromatic anilines, aminopyrimidines, and piperazine amides demonstrate meaningful CNS access. The query's high MW/TPSA and efflux-transporter prior are outweighed by direct experimental evidence, so the prediction is pass.",
  "evidence_gaps": [
    "No direct brain or CSF measurement for the exact query molecule.",
    "Efflux-transporter substrate status of the query is not experimentally confirmed.",
    "The acrylamide group may introduce reactivity or metabolic instability not captured by the analogues.",
    "Human CNS exposure for the query is unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

